declare(strict_types=1);require __DIR__.'/_init.php';if($_SERVER['REQUEST_METHOD']!=='POST')json_response(['ok'=>false,'error'=>'method_not_allowed'],405);$d=json_input();$identity=trim((string)($d['identity']??''));$password=(string)($d['password']??'');$device=trim((string)($d['device_name']??''));if($identity===''||$password==='')json_response(['ok'=>false,'error'=>'missing_credentials'],422);$lookup=filter_var($identity,FILTER_VALIDATE_EMAIL)?normalize_email($identity):$identity;enforce_login_rate_limit($lookup);$q=db()->prepare('SELECT id,username,email,display_name,password_hash FROM users WHERE (email=? OR username=?) AND is_active=1 LIMIT 1');$q->execute([$lookup,$lookup]);$u=$q->fetch();if(!$u||!password_verify($password,$u['password_hash'])){record_login_attempt($lookup,false);usleep(250000);json_response(['ok'=>false,'error'=>'invalid_credentials'],401);}record_login_attempt($lookup,true);$token=issue_api_token((int)$u['id'],$device);unset($u['password_hash']);json_response(['ok'=>true,'token'=>$token,'user'=>$u]);
